@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-add: var(--add);
  --color-del: var(--del);
  --color-warn: var(--warn);
  --radius-sm: calc(var(--radius) * 0.7);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) * 1.3);
  --shadow-card:
    0 1px 2px color-mix(in srgb, var(--foreground) 7%, transparent),
    0 2px 8px color-mix(in srgb, var(--foreground) 4%, transparent);
  --font-sans: "IBM Plex Sans", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Bricolage Grotesque Variable", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, monospace;
}

:root {
  color-scheme: light;
  --motion: 180ms;
  --motion-brief: 500ms;
  --motion-brief-gap: 50ms;
  --motion-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --radius: 0.45rem;
  --background: #f4f6f8;
  --foreground: #171b22;
  --card: #ffffff;
  --card-foreground: #171b22;
  --popover: #ffffff;
  --popover-foreground: #171b22;
  --primary: #3d4fd8;
  --primary-foreground: #ffffff;
  --secondary: #e8ecf1;
  --secondary-foreground: #171b22;
  --muted: #e8ecf1;
  --muted-foreground: #5c6570;
  --accent: #e4e8f4;
  --accent-foreground: #171b22;
  --destructive: #cf222e;
  --border: #d5dbe3;
  --input: #d5dbe3;
  --ring: #3d4fd8;
  --add: #1a7f37;
  --del: #cf222e;
  --warn: #9a6700;
  --add-bg: color-mix(in srgb, #1a7f37 16%, transparent);
  --del-bg: color-mix(in srgb, #cf222e 16%, transparent);
  --diff-canvas: #ffffff;
  --diff-fg: #1f2328;
  --diff-add-line: #e6ffec;
  --diff-add-num: #ccffd8;
  --diff-add-word: #abf2bc;
  --diff-del-line: #ffebe9;
  --diff-del-num: #ffd7d5;
  --diff-del-word: #ff818266;
  --diff-hunk: #ddf4ff;
  --diff-hover: #f6f8fa;
  --strand-0: #2458b5;
  --strand-1: #9a5b00;
  --strand-2: #6b3d96;
  --strand-3: #0b6e78;
  --strand-4: #9a356e;
  --strand-5: #3a5366;
}

.dark {
  color-scheme: dark;
  --background: #12151c;
  --foreground: #e6eaf0;
  --card: #1a1e27;
  --card-foreground: #e6eaf0;
  --popover: #1a1e27;
  --popover-foreground: #e6eaf0;
  --primary: #8b9cff;
  --primary-foreground: #12151c;
  --secondary: #252a33;
  --secondary-foreground: #e6eaf0;
  --muted: #252a33;
  --muted-foreground: #8b939e;
  --accent: #2a3148;
  --accent-foreground: #e6eaf0;
  --destructive: #f85149;
  --border: #2c3340;
  --input: #2c3340;
  --ring: #8b9cff;
  --add: #3fb950;
  --del: #f85149;
  --warn: #d4a017;
  --add-bg: color-mix(in srgb, #3fb950 16%, transparent);
  --del-bg: color-mix(in srgb, #f85149 16%, transparent);
  --diff-canvas: #0d1117;
  --diff-fg: #e6edf3;
  --diff-add-line: rgba(46, 160, 67, 0.15);
  --diff-add-num: rgba(46, 160, 67, 0.4);
  --diff-add-word: rgba(46, 160, 67, 0.4);
  --diff-del-line: rgba(248, 81, 73, 0.15);
  --diff-del-num: rgba(248, 81, 73, 0.4);
  --diff-del-word: rgba(248, 81, 73, 0.4);
  --diff-hunk: rgba(56, 139, 253, 0.1);
  --diff-hover: #161b22;
  --strand-0: #8fb4f0;
  --strand-1: #e0a64a;
  --strand-2: #c9a3e8;
  --strand-3: #6ed0d6;
  --strand-4: #e399c0;
  --strand-5: #9ab0c2;
}

@layer base {
  * {
    @apply border-border;
  }

  html,
  body,
  #root {
    height: 100%;
  }

  html {
    view-transition-name: none;
  }

  body {
    @apply bg-background text-foreground font-sans antialiased;
    font-size: 14px;
    line-height: 1.55;
  }

  @media (max-width: 799px) {
    body {
      font-size: 13px;
      line-height: 1.5;
    }
  }

  code,
  pre,
  kbd {
    font-family: var(--font-mono);
  }
}

::view-transition-old(review-strand),
::view-transition-new(review-strand),
::view-transition-old(review-copy),
::view-transition-new(review-copy),
::view-transition-old(review-overview),
::view-transition-new(review-overview),
::view-transition-old(review-scene),
::view-transition-new(review-scene) {
  mix-blend-mode: normal;
  animation-timing-function: var(--motion-ease);
  animation-fill-mode: both;
}

::view-transition-old(review-strand),
::view-transition-new(review-strand) {
  height: 100%;
  overflow: clip;
  animation-duration: var(--motion-brief);
}

::view-transition-old(review-strand) {
  animation-name: motion-fade-out;
}

::view-transition-new(review-strand) {
  animation-name: motion-fade-in;
}

::view-transition-group(review-strand) {
  animation-duration: var(--motion-brief);
  animation-timing-function: var(--motion-ease);
}

::view-transition-image-pair(review-strand) {
  isolation: isolate;
}

::view-transition-old(review-copy) {
  animation-name: motion-slide-down-out;
  animation-duration: calc((var(--motion-brief) - var(--motion-brief-gap)) / 2);
}

::view-transition-new(review-copy) {
  animation-name: motion-slide-up-in;
  animation-duration: calc((var(--motion-brief) - var(--motion-brief-gap)) / 2);
  animation-delay: calc((var(--motion-brief) + var(--motion-brief-gap)) / 2);
}

::view-transition-group(review-copy) {
  animation: none;
}

::view-transition-old(review-overview) {
  animation-name: motion-fade-out;
  animation-duration: var(--motion-brief);
}

::view-transition-new(review-overview) {
  animation-name: motion-fade-in;
  animation-duration: var(--motion-brief);
}

::view-transition-group(review-overview) {
  animation: none;
}

::view-transition-old(review-scene) {
  animation-name: motion-fade-out;
  animation-duration: var(--motion);
}

::view-transition-new(review-scene) {
  animation-name: motion-fade-in;
  animation-duration: var(--motion);
}

::view-transition-group(review-scene) {
  animation-duration: var(--motion);
  animation-timing-function: var(--motion-ease);
}

::view-transition-image-pair(review-scene) {
  isolation: isolate;
}

@keyframes motion-fade-out {
  to {
    opacity: 0;
  }
}

@keyframes motion-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes motion-slide-down-out {
  to {
    opacity: 0;
    translate: 0 0.75rem;
  }
}

@keyframes motion-slide-up-in {
  from {
    opacity: 0;
    translate: 0 0.75rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }
}
